Lemma grow_credit (s' : PM.vstr) (A : Z) :
  PM.tb_ok s tg -> PM.vs_cap s <= 2 ^ 27 -> 2 * PM.vs_cap s <= PM.vs_cap s' -> PM.vs_cap s' = A - 1 -> A <= 2 ^ 27 ->
  PMSPA.credit_le (scA (PM.pot_text HV s tg)) cr0 ->
